from scipy.ndimage import label

def components(g):
 a=np.array(g); out=[]
 for color in sorted(set(a.flat)-{0}):
  lab,n=label(a==color) # 4 conn
  for k in range(1,n+1):
   ys,xs=np.where(lab==k)
   out.append({'color':int(color),'cells':set(zip(ys.tolist(),xs.tolist())),'area':len(ys),'bbox':(ys.min(),xs.min(),ys.max()+1,xs.max()+1)})
 return sorted(out,key=lambda c:-c['area'])
for nm,g in [('d1',pairs[0]['input']),('d2',pairs[1]['input']),('test',test)]:
 cs=components(g)
 print(nm,[(c['color'],c['area'],c['bbox']) for c in cs])
 main=cs[0]; holes=sum(v==0 for v in np.array(g)[main['bbox'][0]:main['bbox'][2],main['bbox'][1]:main['bbox'][3]].flat)*4
 pieces=sum(c['area'] for c in cs if c['area']>1 and c is not main)
 print('holes',holes,'pieces',pieces)

def crop_cells(c):
 y0,x0,y1,x1=c['bbox']; return frozenset((y-y0,x-x0) for y,x in c['cells'])
def dims(s): return (max(y for y,x in s)+1,max(x for y,x in s)+1)
def norm(s):
 my=min(y for y,x in s); mx=min(x for y,x in s); return frozenset((y-my,x-mx) for y,x in s)
def rotations(s):
 out=[]; cur=set(s)
 for k in range(4):
  z=norm(cur)
  if z not in out: out.append(z)
  h,w=dims(z); cur={(x,h-1-y) for y,x in z}
 return out

def setup(g):
 cs=components(g); main=cs[0]; a=np.array(g); y0,x0,y1,x1=main['bbox']; m=a[y0:y1,x0:x1]
 H,W=m.shape; holes={(y,x) for y in range(H*2) for x in range(W*2) if m[y//2,x//2]==0}
 return main,m,holes,[c for c in cs[1:] if c['area']>1]
for i,p in enumerate(pairs):
 main,m,holes,pcs=setup(p['input']); out=np.array(p['output'])
 print('\ndemo',i+1,'main',main['color'],'holes',len(holes))
 for c in pcs:
  s=crop_cells(c); found=[]
  for k,r in enumerate(rotations(s)):
   h,w=dims(r)
   for y in range(out.shape[0]-h+1):
    for x in range(out.shape[1]-w+1):
     placed={(y+dy,x+dx) for dy,dx in r}
     if placed<=holes and all(out[yy,xx]==c['color'] for yy,xx in placed): found.append((k,y,x))
  print(c['color'],c['area'],dims(s),found)
print('test main pattern')
main,m,holes,pcs=setup(test)
print(m)
print('pieces',[(c['color'],c['area'],dims(crop_cells(c))) for c in pcs])

